import {preferencesPanel,setPreferences,readPreferences,sounds} from './preferences.js';
import {loadingState,loadFailure} from './loading-state.js';
import {NativeSetupFields} from '/native-setup.js';
import {mountConnectionIndicator} from '/connection-indicator.js';
import {mountAISettings,openAIConnectionDialog} from './ai-settings.js';
import {projectScheduleHTML,readReminders} from './schedule-ui.js';
import {libraryIcon,agentAvatar,agentColors,agentIcons,appearanceFor,iconLabel} from '/agent-appearance.js';
import {providerName,providerSetupLabel,endpointProviderIds} from '/providers.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,extra='')=>`<button type="button" data-project-setting="${action}" ${extra}>${label}</button>`;
const badge=resource=>`<span class="availability-badge ${resource.scope==='global'?'global':''}">${libraryIcon(resource.scope==='global'?'globe':'folder',13)}${resource.scope==='global'?'Global':'Project'}</span>`;
const assignment=resource=>resource.assignment==='selected'?`${(resource.agentIds||[]).length} session${resource.agentIds?.length===1?'':'s'} · ${(resource.profileIds||[]).length} profile${resource.profileIds?.length===1?'':'s'}`:'All agents in scope';
const status=server=>({ready:'Tools discovered',disabled:'Disabled',error:'Connection needs attention','not-connected':'Not connected'})[server.status]||'Not connected';

export class ProjectSettingsDialog {
  constructor(trigger,{api,project,onSaved,onUseProfile,tab='agents',sourceTaskId,serverId}){
    Object.assign(this,{trigger,api,project,onSaved,onUseProfile,tab,sourceTaskId,serverId});this.filter='project';
    this.host=document.createElement('dialog');this.host.className='project-settings-dialog';this.host.setAttribute('aria-label','Project Settings');
    this.host.innerHTML=`<header class="project-settings-head"><h2>Project Settings</h2>${button('close','×','aria-label="Close project settings"')}</header><div class="settings-loading">${loadingState('Loading project settings',{detail:'Gathering agent profiles, tools and connections.'})}</div><p class="project-settings-feedback" role="status"></p>`;document.body.append(this.host);this.host.showModal();
    this.host.addEventListener('cancel',event=>{event.preventDefault();if(!this.busy)this.close();});
    this.host.addEventListener('click',event=>{const target=event.target.closest('[data-project-setting]');if(target)this.action(target).catch(e=>this.error(e));});
    this.host.addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();this.save(event.target).catch(e=>this.error(e));});
    this.host.addEventListener('change',event=>this.change(event.target));
    this.refresh().then(()=>{
      if(this.closed)return;
      if(this.sourceTaskId){const task=this.data.agents.find(a=>a.id===this.sourceTaskId);if(task)this.edit('agent',task.profileId?this.data.profiles.find(p=>p.id===task.profileId):null,task.profileId?null:task);}
      else if(this.serverId){const server=this.data.mcps.find(s=>s.id===this.serverId);if(server)this.edit('mcp',server);}
    }).catch(e=>this.error(e));
  }
  error(error){if(this.closed)return;if(error&&!this.data){this.host.querySelector('.settings-loading').innerHTML=loadFailure('Project settings couldn’t load',{detail:error.message,retry:'data-project-setting="retry-load"'});return;}const text=error?.message||'';const host=this.host.querySelector('.project-settings-feedback')||this.host;host.textContent=text;if(text)host.scrollIntoView({block:'nearest'});}
  projectName(id){return this.data.projects.find(p=>p.id===id)?.name||id?.split('/').pop()||'All projects';}
  async refresh(){const data=await this.api('project-settings?project='+encodeURIComponent(this.project));if(this.closed)return;this.data=data;this.render();}
  visible(resource){return this.filter==='all'||this.filter==='global'&&resource.scope==='global'||this.filter==='project'&&(resource.scope==='global'||resource.project===this.project);}
  render(){
    if(this.closed)return;
    this.host.innerHTML=`<header class="project-settings-head"><span class="settings-mark">${libraryIcon('settings-2',23)}</span><div><span class="eyebrow">YOUR WORKSPACE, YOUR TEAM</span><h2>Project Settings</h2></div>${button('close','×','aria-label="Close project settings"')}</header><div class="project-settings-context"><label>Project<select name="settings-project" aria-label="Project to configure">${this.data.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===this.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><span>Shared profiles. Project-specific work.</span></div><nav class="project-settings-tabs" aria-label="Project settings sections">${button('appearance',libraryIcon('palette')+' Appearance & Sound',`aria-pressed="${this.tab==='appearance'}"`)}${button('conversation',libraryIcon('message-circle')+' Conversation',`aria-pressed="${this.tab==='conversation'}"`)}${button('agents',libraryIcon('bot')+' Agents',`aria-pressed="${this.tab==='agents'}"`)}${button('tools',libraryIcon('wrench')+' Tools & MCPs',`aria-pressed="${this.tab==='tools'}"`)}${button('ai',libraryIcon('brain')+' AI & Context',`aria-pressed="${this.tab==='ai'}"`)}${button('schedule',libraryIcon('calendar')+' Schedule & Reminders',`aria-pressed="${this.tab==='schedule'}"`)}</nav><div class="project-settings-body"></div><p class="project-settings-feedback" role="status"></p>`;
    this.renderBody();
  }
  renderBody(){
    if(this.editor){this.renderEditor();return;}
    if(this.tab==='conversation'){
      const setting=this.data.conversation||{style:'conversational',revision:0};
      this.host.querySelector('.project-settings-body').innerHTML=`<section class="app-preferences"><h3>How Your Team Talks</h3><p>Choose the tone for this project's agents. It applies to new sessions and their next delivered messages.</p><fieldset><legend>Conversation Style</legend><div class="appearance-choices">${[['concise','Concise','Brief, precise updates.'],['conversational','Conversational','Natural, warm, and direct.'],['expressive','Expressive','More personality and encouragement.']].map(([value,label,detail])=>`<label><input type="radio" name="conversation-style" value="${value}" ${setting.style===value?'checked':''}><span><strong>${label}</strong><small>${detail}</small></span></label>`).join('')}</div></fieldset><p>Task evidence and review rules stay the same. This changes writing guidance; it does not rewrite saved chats or start extra model turns.</p><p class="conversation-saved" role="status">Changes save automatically for this project.</p></section>`;return;
    }
    if(this.tab==='appearance'){this.host.querySelector('.project-settings-body').innerHTML=preferencesPanel();return;}
    if(this.tab==='ai'){mountAISettings(this.host.querySelector('.project-settings-body'),{api:this.api,onSaved:()=>this.onSaved()}).catch(e=>this.error(e));return;}
    if(this.tab==='schedule'){this.host.querySelector('.project-settings-body').innerHTML=projectScheduleHTML(this.data);return;}
    const profiles=this.data.profiles.filter(p=>this.visible(p)),servers=this.data.mcps.filter(s=>this.visible(s)),tools=this.data.tools.filter(t=>this.visible(t));
    const sessions=this.data.agents.filter(a=>!a.profileId&&!a.archived&&this.filter!=='global'&&(this.filter==='all'||a.project===this.project));
    this.host.querySelector('.project-settings-body').innerHTML=`<div class="settings-section-intro"><div><h3>${this.tab==='agents'?'The Right Team For Every Project':'Build Your Project Toolbox'}</h3><p>${this.tab==='agents'?'Make an agent reusable in one project or across all projects. Each new task gets its own session, conversation, and worktree.':'Choose where a tool is available, then which agents can use it. Changes apply to existing sessions and future tool calls.'}</p></div>${this.tab==='agents'?button('new-agent',libraryIcon('plus',16)+' New agent profile','class="primary"'):button('new-mcp',libraryIcon('plus',16)+' Connect MCP','class="primary"')}</div><div class="settings-scope-filters" role="group" aria-label="Resource availability">${[['project','This project + global'],['global','Global only'],['all','All projects']].map(([id,label])=>button('filter',label,`data-filter="${id}" aria-pressed="${this.filter===id}"`)).join('')}</div>${this.tab==='agents'?`
      <div class="profile-grid">${profiles.map(p=>`<article class="profile-card">${agentAvatar({...p,role:p.name},23)}<div><h4>${esc(p.name)}</h4><small>${esc(providerName(p.kind))}${p.model?' · '+esc(p.model):''}</small><p>${esc(p.summary)}</p><div class="resource-labels">${badge(p)}${p.builtIn?'<span class="profile-template-badge">Built-in template</span>':''}<span>${p.scope==='global'?'Every project':esc(this.projectName(p.project))}</span><span>${p.sessions.length} saved session${p.sessions.length===1?'':'s'}</span></div></div><footer>${!p.builtIn?button('edit-agent','Manage',`data-id="${p.id}"`):''}${button('duplicate-agent',p.builtIn?'Duplicate & customize':'Duplicate',`data-id="${p.id}"`)}${button('use-agent','Use in this project →',`data-id="${p.id}" ${(p.scope!=='global'&&p.project!==this.project)||!this.data.providers.find(x=>x.id===p.kind)?.installed?'disabled':''}`)}</footer></article>`).join('')}</div>${sessions.length?`<div class="settings-subheading"><h4>Project Agents</h4><span>Give an existing agent a reusable profile</span></div><div class="project-agent-list">${sessions.map(a=>`<article>${agentAvatar(a)}<div><strong>${esc(a.role)}</strong><small>${esc(this.projectName(a.project))} · ${esc(providerName(a.kind))}</small></div>${button('reuse-agent','Make reusable',`data-id="${a.id}"`)}</article>`).join('')}</div>`:''}${!profiles.length&&!sessions.length?'<div class="settings-empty">No agents in this view yet. Create a profile to define their role and availability.</div>':''}
      <p class="settings-note">A shared profile keeps its color and icon across all linked sessions, including past conversations. Changing availability affects future use; existing sessions keep their project and history.</p>`:`
      <div class="settings-subheading"><h4>MCP Connections <span>${servers.length}</span></h4><span>Grouped by source</span></div><div class="mcp-server-list">${servers.map(s=>this.serverHTML(s)).join('')||`<div class="settings-empty">${libraryIcon('plug',28)}<strong>Bring your tools together</strong><p>Connect an MCP server and choose who can use its tools.</p>${button('aws',libraryIcon('globe',16)+' Set up AWS Knowledge')}</div>`}</div>
      <div class="settings-subheading"><h4>Local Tools <span>${tools.length}</span></h4>${button('new-tool',libraryIcon('plus',14)+' Register executable')}</div><div class="local-tool-list">${tools.map(t=>`<article><span class="resource-icon">${libraryIcon('terminal',20)}</span><div><strong>${esc(t.name)}</strong><p>${esc(t.description)}</p><div class="resource-labels">${badge(t)}<span>${esc(assignment(t))}${t.enabled===false?' · Disabled':''}</span></div></div>${button('edit-tool','Manage',`data-id="${t.id}"`)}</article>`).join('')||'<p class="settings-note">No local executables in this view.</p>'}</div><p class="settings-note">These settings control tools served through HeloScrum. Your agent provider’s own shell, browser, and MCP configuration remain separate.</p>`}`;
  }
  serverHTML(s){
    return `<details class="mcp-group" data-mcp="${s.id}"><summary><span class="resource-icon">${libraryIcon('plug',20)}</span><span class="mcp-title"><strong>${esc(s.name)}</strong><small>${esc(status(s))} · ${s.tools.length} tools · ${esc(assignment(s))}</small></span>${badge(s)}${libraryIcon('chevron-down',17)}</summary><div class="mcp-group-body"><div class="mcp-connection-info"><span>${esc(s.transport==='http'?s.url:s.command)}<small>${s.scope==='global'?'Available in all projects':esc(this.projectName(s.project))}${s.hasCredentials?' · Credentials saved locally':''}</small></span>${button('edit-mcp',libraryIcon('settings-2',15)+' Manage',`data-id="${s.id}"`)}${button('connect','Refresh tools',`data-id="${s.id}" ${s.enabled===false?'disabled':''}`)}</div>${s.lastError?`<p class="connection-warning">${esc(s.lastError)}</p>`:''}<div class="mcp-tool-rows">${s.tools.map(t=>`<div><code>${esc(t.name)}</code>${t.annotations?.readOnlyHint?'<span class="tool-annotation">Read only</span>':''}<p>${esc(t.description)}</p></div>`).join('')||'<p class="settings-note">Connect to discover this server’s tools.</p>'}</div></div></details>`;
  }
  edit(type,item=null,source=null){if(type==='agent'&&item?.builtIn)item={...item,id:null,name:item.name+' copy',sourceProfileId:item.id,builtIn:false,sessions:[]};this.editor={type,item,source};this.renderBody();this.host.querySelector('.project-settings-body').scrollTop=0;this.host.querySelector('form input')?.focus();}
  scopeFields(item){return `<fieldset class="resource-scope"><legend>Availability</legend><div class="form-pair"><label>Available In<select name="scope"><option value="project" ${item.scope!=='global'?'selected':''}>One project</option><option value="global" ${item.scope==='global'?'selected':''}>All projects · Global</option></select></label><label data-project-field>Project<select name="project">${this.data.projects.map(p=>`<option value="${esc(p.id)}" ${(item.project||this.project)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><p class="settings-note">${this.editor.type==='agent'?'This controls where the profile can start new sessions.':'Global tools are available across projects. Limit access further with agent assignment below.'}</p></fieldset>`;}
  assignmentFields(item){return `<fieldset class="resource-assignment"><legend>Agent Assignment</legend><label>Who Can Use These Tools?<select name="assignment"><option value="all" ${item.assignment!=='selected'?'selected':''}>All agents in scope</option><option value="selected" ${item.assignment==='selected'?'selected':''}>Only selected agents</option></select></label><div class="assignment-choices"></div><label class="settings-check"><input type="checkbox" name="enabled" ${item.enabled!==false?'checked':''}>Enabled</label></fieldset>`;}
  updateAccess(){
    const form=this.host.querySelector('form'),scope=form.elements.scope.value,project=form.elements.project.value;
    form.querySelector('[data-project-field]').hidden=scope==='global';
    const list=form.querySelector('.assignment-choices');if(!list)return;
    const previous=this.editor.selection||this.editor.item||{};
    list.hidden=form.elements.assignment.value!=='selected';
    const profiles=this.data.profiles.filter(p=>scope==='global'||p.scope==='global'||p.project===project),agents=this.data.agents.filter(a=>(!a.archived||(previous.agentIds||[]).includes(a.id))&&(scope==='global'||a.project===project));
    list.innerHTML=`<p class="settings-note">Choose a profile to include its current and future sessions, or choose individual sessions. Explicit assignments also enable these tools in the selected agent’s toolbox.</p>${profiles.length?'<strong>Reusable profiles</strong>':''}${profiles.map(p=>`<label class="settings-check">${`<input type="checkbox" name="profileIds" value="${p.id}" ${(previous.profileIds||[]).includes(p.id)?'checked':''}>`}${agentAvatar(p,14)}<span>${esc(p.name)}<small>${p.scope==='global'?'Global profile':esc(this.projectName(p.project))}</small></span></label>`).join('')}<strong>Project sessions</strong>${agents.map(a=>`<label class="settings-check"><input type="checkbox" name="agentIds" value="${a.id}" ${(previous.agentIds||[]).includes(a.id)?'checked':''}>${agentAvatar(a,14)}<span>${esc(a.role)}<small>${esc(this.projectName(a.project))}</small></span></label>`).join('')||'<p>No active sessions in this project yet. Use all agents or create a profile first.</p>'}`;
  }
  renderEditor(){
    const {type,item:original,source}=this.editor,item=original||source&&{...source,name:source.role}||{},title=type==='agent'?(original?.id?'Manage Agent Profile':'Create Agent Profile'):type==='mcp'?(original?'Manage MCP Connection':'Connect An MCP Server'):(original?'Manage Local Tool':'Register A Local Tool');
    this.host.querySelector('.project-settings-body').innerHTML=`${button('back','← Back','class="settings-back"')}<h3>${title}</h3><form class="project-resource-form" id="pack-project-resource"><fieldset class="resource-definition"><legend>${type==='agent'?'Agent Profile':type==='mcp'?'Connection':'Executable'}</legend>${type==='agent'?`
      ${original?.sourceProfileId&&!original.id?'<p class="settings-note">Customize this independent copy. The source profile and its existing sessions stay linked to their original profile.</p>':''}${source?'<p class="settings-note">This session will be linked to the new profile. Its files and conversation stay here.</p>':''}<div class="form-pair"><label>Name<input name="name" required maxlength="80" value="${esc(item.name)}" placeholder="Cloud architect"></label><label>Provider<select name="kind" aria-label="Provider">${this.data.providers.map(p=>`<option value="${p.id}" ${p.id===(item.kind||'codex')?'selected':''}>${esc(providerName(p.id))}${esc(providerSetupLabel(p.id,p.installed))}</option>`).join('')}</select></label></div><div data-profile-connection><label>AI Connection<select name="connectionId"></select></label><p class="settings-note" data-connection-note></p>${button('setup-connection','Set Up A Connection')}<div data-connection-status></div></div><label>Role Summary<input name="summary" required maxlength="1000" value="${esc(item.summary)}" placeholder="Infrastructure, architecture, and AWS documentation"></label><label>Shared Instructions<textarea name="instructions" required maxlength="16000" rows="4" placeholder="Describe this agent’s expertise and how it should work.">${esc(item.instructions)}</textarea></label><div class="form-pair"><label>Model ID (Optional)<input name="model" maxlength="150" value="${esc(item.model)}" placeholder="Provider default"></label><label>Role Type<select name="roleType"><option value="worker" ${item.roleType!=='recovery'?'selected':''}>Coding teammate</option><option value="recovery" ${item.roleType==='recovery'?'selected':''}>Recovery coach</option></select></label></div><div class="form-pair"><label>Color<select name="color">${agentColors.map(c=>`<option value="${c.id}" ${appearanceFor(item).color===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Icon<select name="icon">${agentIcons.map(i=>`<option value="${i}" ${appearanceFor(item).icon===i?'selected':''}>${iconLabel(i)}</option>`).join('')}</select></label></div><div data-native-profile></div><div class="profile-form-preview">${agentAvatar({appearance:appearanceFor(item)},24)}<strong>${esc(item.name||'Your Agent')}</strong></div><p class="settings-note">Appearance updates every linked session, including previous chats. Profile instructions and provider defaults apply to new sessions.</p>`:type==='mcp'?`
      ${!original?`<div class="mcp-preset">${button('aws',libraryIcon('globe',16)+' AWS Knowledge preset')}<small>Public AWS documentation MCP</small></div>`:''}<label>MCP Name<input name="name" required maxlength="100" value="${esc(item.name)}" placeholder="AWS Knowledge"></label><label>Connection Type<select name="transport"><option value="http" ${item.transport!=='stdio'?'selected':''}>Remote · Streamable HTTP</option><option value="stdio" ${item.transport==='stdio'?'selected':''}>Local · stdio command</option></select></label><div data-transport="http"><label>Endpoint URL<input name="url" type="url" value="${esc(item.url)}" placeholder="https://knowledge-mcp.global.api.aws"></label><details class="mcp-credentials"><summary>Authentication Headers ${item.hasCredentials?'· saved':''}</summary><p class="settings-note">Use a server-provided API key or Authorization header. Browser OAuth sign-in is not supported here yet.</p><label>Headers (JSON)<textarea name="headers" rows="3" autocomplete="off" spellcheck="false" placeholder='{"Authorization":"Bearer …"}'></textarea></label></details></div><div data-transport="stdio"><label>Command<input name="command" value="${esc(item.command)}" placeholder="uvx or /absolute/path/to/server"></label><label>Arguments (JSON Array)<textarea name="args" rows="2" spellcheck="false">${esc(JSON.stringify(item.args||[]))}</textarea></label><details class="mcp-credentials"><summary>Environment Variables ${item.hasCredentials?'· saved':''}</summary><label>Environment (JSON)<textarea name="env" rows="3" autocomplete="off" spellcheck="false" placeholder='{"API_KEY":"…"}'></textarea></label></details><p class="settings-note">Save & connect starts this command with your local permissions. Each project uses a separate MCP connection.</p></div>${item.hasCredentials?`<p class="settings-note">Saved credential names: ${esc([...(item.credentialNames?.headers||[]),...(item.credentialNames?.env||[])].join(', '))}. Leave blank to keep them.</p><label class="settings-check"><input type="checkbox" name="clearCredentials">Remove saved credentials</label>`:''}<p class="settings-note">Credentials stay in a private local file and are excluded from HeloScrum history exports. Use the fields above for secrets, not command arguments.</p>`:`
      <label>Tool Name<input name="name" required pattern="[a-z][a-z0-9_]+" value="${esc(item.name)}" ${original?'readonly':''} placeholder="refresh_aws_creds"></label><label>Description<textarea name="description" required rows="2" ${original?'readonly':''}>${esc(item.description)}</textarea></label>${original?`<p class="settings-note"><code>${esc(item.executable)}</code></p>`:'<label>Executable Path<input name="executable" required placeholder="/absolute/path/to/tool"></label><label>Arguments (JSON Array)<input name="args" value="[]" required></label><label>Input Schema (JSON)<textarea name="inputSchema" rows="5" spellcheck="false">{"type":"object","properties":{},"additionalProperties":false}</textarea></label><p class="settings-note">Receives JSON on stdin and returns stdout. Runs with your local permissions when an assigned agent calls it.</p>'}`}</fieldset>${this.scopeFields(item)}${type!=='agent'?this.assignmentFields(item):''}<footer class="project-resource-actions">${button('back','Cancel')}<button type="submit" class="primary">${type==='mcp'?'Save & connect':type==='agent'?'Save agent profile':'Save tool access'}</button></footer></form>`;
    this.updateAccess();this.updateTransport();
    if(type==='agent')this.updateConnection(item.connectionId);
    if(type==='agent')new NativeSetupFields(this.host.querySelector('[data-native-profile]'),{api:this.api,kind:item.kind||'codex',project:this.host.querySelector('[name=project]')?.value||this.project,value:item.nativeSetup});
  }
  updateConnection(selected){
    const form=this.host.querySelector('#pack-project-resource'),kind=form?.elements.kind?.value;if(!kind)return;
    const field=form.querySelector('[data-profile-connection]'),select=form.elements.connectionId;field.hidden=!endpointProviderIds.includes(kind);select.disabled=field.hidden;select.required=!field.hidden;
    const connections=(this.data.aiConnections||[]).filter(c=>c.kind===kind&&c.enabled!==false&&c.supportsTools),previous=selected??select.value;
    select.innerHTML=connections.length?connections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.model||'Choose a model')}</option>`).join(''):'<option value="">Set Up A Connection First</option>';
    if(connections.some(c=>c.id===previous))select.value=previous;
    field.querySelector('[data-connection-note]').textContent=connections.length?'Choose the saved model server for this agent.':'Connect your model server here. Your agent form will stay open while you set it up.';
    const savedConnection=connections.find(c=>c.id===select.value),setup=field.querySelector('[data-project-setting=setup-connection]');
    setup.textContent='Set Up '+providerName(kind);setup.hidden=!!savedConnection;
    mountConnectionIndicator(field.querySelector('[data-connection-status]'),{api:this.api,connection:savedConnection});
    for(const option of form.elements.kind.options){const provider=this.data.providers.find(p=>p.id===option.value);option.textContent=providerName(option.value)+providerSetupLabel(option.value,provider?.installed);}
  }
  updateTransport(){const form=this.host.querySelector('form');if(!form?.elements.transport)return;for(const box of form.querySelectorAll('[data-transport]')){box.hidden=box.dataset.transport!==form.elements.transport.value;for(const field of box.querySelectorAll('input,textarea'))field.disabled=box.hidden;}form.elements.url.required=form.elements.transport.value==='http';form.elements.command.required=form.elements.transport.value==='stdio';}
  change(target){
    if(target.name==='conversation-style'){
      const previous=this.data.conversation||{style:'conversational',revision:0};
      this.working('Saving conversation style…',async()=>{
        this.data.conversation=await this.api('project-settings/conversation',{project:this.project,style:target.value,expectedRevision:previous.revision});
        this.host.querySelector('.conversation-saved').textContent='Conversation style saved.';
      }).catch(e=>{const old=this.host.querySelector(`[name=conversation-style][value="${previous.style}"]`);if(old)old.checked=true;this.error(e);});return;
    }
    if(['app-theme','app-sounds'].includes(target.name)){setPreferences(target.name==='app-theme'?{theme:target.value}:{sounds:target.checked});for(const preview of this.host.querySelectorAll('[data-project-setting=preview-sound]'))preview.disabled=!this.host.querySelector('[name=app-sounds]').checked;if(target.name==='app-sounds'&&target.checked)sounds.unlock();this.host.querySelector('.appearance-saved').textContent='Preferences saved.';return;}
    if(this.busy)return;
    if(target.name==='settings-project'){this.project=target.value;this.editor=null;this.refresh().catch(e=>this.error(e));return;}
    if(['agentIds','profileIds'].includes(target.name)){const form=this.host.querySelector('form');this.editor.selection={agentIds:[...form.querySelectorAll('[name=agentIds]:checked')].map(e=>e.value),profileIds:[...form.querySelectorAll('[name=profileIds]:checked')].map(e=>e.value)};}
    if(['scope','project','assignment'].includes(target.name))this.updateAccess();
    if(target.name==='project'&&this.editor?.type==='agent'){const host=this.host.querySelector('[data-native-profile]');new NativeSetupFields(host,{api:this.api,kind:this.host.querySelector('[name=kind]').value,project:target.value});}
    if(target.name==='kind'&&this.editor?.type==='agent'){this.updateConnection();new NativeSetupFields(this.host.querySelector('[data-native-profile]'),{api:this.api,kind:target.value,project:this.host.querySelector('[name=project]')?.value||this.project});}
    if(target.name==='connectionId'&&this.editor?.type==='agent')this.updateConnection(target.value);
    if(target.name==='transport')this.updateTransport();
    if(['color','icon'].includes(target.name)){const form=this.host.querySelector('form');this.host.querySelector('.profile-form-preview').innerHTML=agentAvatar({appearance:{color:form.elements.color.value,icon:form.elements.icon.value}},24)+'<strong>'+esc(form.elements.name.value||'Your Agent')+'</strong>';}
    if(target.name==='enabled'&&this.editor.type==='mcp')this.host.querySelector('[type=submit]').textContent=target.checked?'Save & connect':'Save settings';
  }
  async action(target){
    if(target.dataset.projectSetting==='retry-load'){this.host.querySelector('.settings-loading').innerHTML=loadingState('Loading project settings');return this.refresh();}
    const action=target.dataset.projectSetting;if(this.busy)return;this.error(null);
    if(action==='close'){this.close();return;}
    if(action==='back'){this.editor=null;this.renderBody();return;}
    if(action==='preview-sound'){await sounds.unlock();const played=await sounds.play(target.dataset.sound||'complete',{preview:true});const status=this.host.querySelector('.appearance-saved');if(status)status.textContent=played?'Playing sound preview.':readPreferences().sounds?'Sound preview is unavailable. Try again.':'Sounds are off.';return;}
    if(['appearance','conversation','agents','tools','schedule','ai'].includes(action)){this.tab=action;this.editor=null;this.render();return;}
    if(action==='filter'){this.filter=target.dataset.filter;this.renderBody();return;}
    if(action==='setup-connection')return openAIConnectionDialog(target,{api:this.api,kind:this.host.querySelector('[name=kind]').value,onSaved:async connection=>{const data=await this.api('project-settings?project='+encodeURIComponent(this.project));this.data.providers=data.providers;this.data.aiConnections=data.aiConnections;if(this.closed)return;this.updateConnection(connection.id);const model=this.host.querySelector('[name=model]');if(model&&!model.value)model.value=connection.model||'';await this.onSaved();}});
    if(action==='new-agent')this.edit('agent');
    if(action==='reuse-agent')this.edit('agent',null,this.data.agents.find(a=>a.id===target.dataset.id));
    if(action==='duplicate-agent'){const p=this.data.profiles.find(p=>p.id===target.dataset.id);this.edit('agent',{...p,id:null,name:p.name+' copy',sourceProfileId:p.id,builtIn:false,sessions:[]});}
    if(action==='edit-agent')this.edit('agent',this.data.profiles.find(p=>p.id===target.dataset.id));
    if(action==='use-agent'){const profile=this.data.profiles.find(p=>p.id===target.dataset.id);await this.onUseProfile(profile,this.project);this.close();}
    if(action==='new-mcp')this.edit('mcp');
    if(action==='edit-mcp')this.edit('mcp',this.data.mcps.find(s=>s.id===target.dataset.id));
    if(action==='new-tool')this.edit('tool');
    if(action==='edit-tool')this.edit('tool',this.data.tools.find(t=>t.id===target.dataset.id));
    if(action==='aws'){this.edit('mcp');const form=this.host.querySelector('form');form.elements.name.value='AWS Knowledge';form.elements.url.value='https://knowledge-mcp.global.api.aws';}
    if(action==='connect')await this.working('Discovering MCP tools…',async()=>{await this.api('project-settings/mcp/connect',{id:target.dataset.id});await this.refresh();await this.onSaved();this.host.querySelector(`[data-mcp="${target.dataset.id}"]`).open=true;});
  }
  async working(label,fn){if(this.busy)return;this.busy=true;this.host.setAttribute('aria-busy','true');this.error({message:label});const controls=[...this.host.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);for(const [e] of controls)e.disabled=true;try{await fn();this.error(null);}finally{this.busy=false;this.host.removeAttribute('aria-busy');for(const [e,disabled] of controls)if(e.isConnected)e.disabled=disabled;}}
  async save(form){
    if(this.busy)return;
    if(form.id==='pack-project-schedule'){const settings=readReminders(form,{project:true});await this.working('Saving reminder settings…',async()=>{await this.api('work/schedule-settings',{project:this.project,settings,expectedRevision:this.data.schedule.revision});await this.refresh();await this.onSaved();});this.error({message:'Reminder settings saved.'});return;}
    const {type,item,source}=this.editor,values=Object.fromEntries(new FormData(form)),data={...values,scope:values.scope,project:values.scope==='global'?null:values.project};
    if(item?.id){data.id=item.id;data.expectedRevision=item.revision;}else if(item?.sourceProfileId)data.sourceProfileId=item.sourceProfileId;
    if(type==='agent'){data.nativeSetup=this.host.querySelector('[data-native-profile]')?.nativeSetup?.value();data.appearance={color:values.color,icon:values.icon};if(source)data.sourceTaskId=source.id;}
    else{data.enabled=!!values.enabled;data.agentIds=[...form.querySelectorAll('[name=agentIds]:checked')].map(e=>e.value);data.profileIds=[...form.querySelectorAll('[name=profileIds]:checked')].map(e=>e.value);}
    if(type==='mcp'){
      for(const key of ['headers','env']){delete data[key];if(values[key]?.trim())data[key]=JSON.parse(values[key]);}
      if(values.transport==='stdio')data.args=JSON.parse(values.args||'[]');data.clearCredentials=!!values.clearCredentials;
    }
    if(type==='tool'&&!item){data.args=JSON.parse(values.args||'[]');data.inputSchema=JSON.parse(values.inputSchema);}
    await this.working(type==='mcp'?'Saving connection and discovering tools…':'Saving settings…',async()=>{
      const saved=await this.api(type==='tool'&&!item?'toolbox':'project-settings/'+(type==='agent'?'agent':type),data);
      if(!this.visible(saved))this.filter='all';
      if(type==='mcp'){
        this.editor.item=saved;
        try{if(data.enabled)await this.api('project-settings/mcp/connect',{id:saved.id});}
        catch(error){this.editor=null;await this.refresh();await this.onSaved();this.host.querySelector(`[data-mcp="${saved.id}"]`).open=true;throw error;}
      }
      this.editor=null;await this.refresh();await this.onSaved();
      if(type==='mcp'){const group=this.host.querySelector(`[data-mcp="${saved.id}"]`);if(group)group.open=true;}
    });
  }
  close(){if(this.closed)return;this.closed=true;this.host.close();this.host.remove();if(this.trigger?.isConnected)this.trigger.focus();}
}
